// Some portions generated by Codex
package org.eclipse.rdf4j.rio.helpers;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertThrows;

import java.util.List;

import org.junit.jupiter.api.Test;

/** Exact unescape contracts, including currently accepted forms outside the N-Triples grammar. */
class NTriplesUtilCompatibilityTest {

	@Test
	void unescapedInputRetainsIdentityIncludingUnicodeAndLoneSurrogates() {
		for (String value : List.of("", "ordinary ASCII", "αשלום😀", "\0\t\n\r\b\f", "\uD800", "\uDFFF",
				"before\uD800middle\uDFFFafter", "\uFFFF")) {
			String input = new String(value.toCharArray());
			assertSame(input, NTriplesUtil.unescapeString(input));
		}
	}

	@Test
	void ordinaryEscapesDecodeWithoutRescanningDecodedBackslashes() {
		String[][] cases = {
				{ "\\t", "\t" },
				{ "\\b", "\b" },
				{ "\\n", "\n" },
				{ "\\r", "\r" },
				{ "\\f", "\f" },
				{ "\\\"", "\"" },
				{ "\\'", "'" },
				{ "\\\\", "\\" },
				{ "\\t\\b\\n\\r\\f\\\"\\'\\\\", "\t\b\n\r\f\"'\\" },
				{ "\\\\n", "\\n" },
				{ "\\\\u0041", "\\u0041" },
				{ "\\u005Cu0041", "\\u0041" },
				{ "\\\\\\n", "\\\n" }
		};
		for (String[] testCase : cases) {
			assertEquals(testCase[1], NTriplesUtil.unescapeString(testCase[0]), testCase[0]);
		}
	}

	@Test
	void longUntouchedSpansSurviveMixedAdjacentAndTerminalEscapes() {
		String prefix = "prefix-α😀".repeat(257);
		String middle = "middle-שלום".repeat(257);
		String suffix = "suffix-\uD800-\uDFFF".repeat(257);
		String input = prefix + "\\n\\t" + middle + "\\u03B1\\U0001F600" + suffix + "\\\\";
		assertEquals(prefix + "\n\t" + middle + "α😀" + suffix + "\\", NTriplesUtil.unescapeString(input));
		assertEquals("\n" + prefix + "\t", NTriplesUtil.unescapeString("\\n" + prefix + "\\t"));
		assertEquals(prefix + "\n" + suffix, NTriplesUtil.unescapeString(prefix + "\\n" + suffix));
	}

	@Test
	void unicodeEscapesPreserveBmpAndSupplementaryBoundaries() {
		List<CodePointCase> cases = List.of(
				new CodePointCase("\\u0000", 0x0000),
				new CodePointCase("\\u0001", 0x0001),
				new CodePointCase("\\u007F", 0x007F),
				new CodePointCase("\\u0080", 0x0080),
				new CodePointCase("\\uD7FF", 0xD7FF),
				new CodePointCase("\\uE000", 0xE000),
				new CodePointCase("\\uFFFF", 0xFFFF),
				new CodePointCase("\\U00000000", 0x0000),
				new CodePointCase("\\U0000FFFF", 0xFFFF),
				new CodePointCase("\\U00010000", 0x10000),
				new CodePointCase("\\U0010FFFF", 0x10FFFF),
				new CodePointCase("\\U0001f600", 0x1F600));
		for (CodePointCase testCase : cases) {
			String expected = new String(Character.toChars(testCase.codePoint()));
			assertEquals(expected, NTriplesUtil.unescapeString(testCase.escaped()), testCase.escaped());
			assertEquals("before" + expected + "after",
					NTriplesUtil.unescapeString("before" + testCase.escaped() + "after"), testCase.escaped());
		}
	}

	@Test
	void signedAndNonAsciiHexadecimalFormsKeepTheirAcceptedValues() {
		List<CodePointCase> cases = List.of(
				new CodePointCase("\\u+041", 0x41),
				new CodePointCase("\\u-000", 0),
				new CodePointCase("\\U+0000041", 0x41),
				new CodePointCase("\\U-0000000", 0),
				new CodePointCase("\\U+010FFFF", 0x10FFFF),
				new CodePointCase("\\u１２３４", 0x1234),
				new CodePointCase("\\uＦＦＦＦ", 0xFFFF),
				new CodePointCase("\\u٠٠٤١", 0x41),
				new CodePointCase("\\u+ＦＦＦ", 0xFFF),
				new CodePointCase("\\u-０００", 0),
				new CodePointCase("\\U０００１Ｆ６００", 0x1F600));
		for (CodePointCase testCase : cases) {
			assertEquals(new String(Character.toChars(testCase.codePoint())),
					NTriplesUtil.unescapeString(testCase.escaped()), testCase.escaped());
		}
	}

	@Test
	void incompleteUnicodeEscapesKeepExactMessagesIncludingOriginalInput() {
		for (String prefix : List.of("", "already\\tdecoded-")) {
			for (String escaped : List.of("\\u", "\\u0", "\\u00", "\\u000", "\\uG",
					"\\U", "\\U0", "\\U00", "\\U000", "\\U0000", "\\U00000", "\\U000000", "\\U0000000")) {
				String input = prefix + escaped;
				assertMessage(input, "Incomplete Unicode escape sequence in: " + input);
			}
		}
	}

	@Test
	void unknownAndTrailingEscapesKeepExactMessagesIncludingOriginalInput() {
		for (String prefix : List.of("", "already\\nchanged-")) {
			for (String escaped : List.of("\\", "\\q", "\\x20", "\\a", "\\N", "\\v", "\\ ", "\\\n", "\\\uD800")) {
				String input = prefix + escaped;
				assertMessage(input, "Unescaped backslash in: " + input);
			}
		}
	}

	@Test
	void malformedHexadecimalEscapesKeepExactTokenAndInputMessages() {
		for (String escaped : List.of("\\u12G4", "\\u 041", "\\u++41", "\\u＋041", "\\u00\\n",
				"\\UFFFFFFFF", "\\U80000000", "\\U0000000G", "\\U+00000G1")) {
			for (String prefix : List.of("", "prefix\\t")) {
				String input = prefix + escaped + "-suffix";
				assertMessage(input, "Illegal Unicode escape sequence '" + escaped + "' in: " + input);
			}
		}
	}

	@Test
	void surrogateEscapesRemainRejectedEvenWhenPaired() {
		for (String escaped : List.of("\\uD800", "\\uDFFF", "\\U0000D800", "\\U0000DFFF",
				"\\U+000D800", "\\uD83D\\uDE00")) {
			String input = "prefix\\n" + escaped + "suffix";
			assertMessage(input, "Illegal Unicode escape sequence: " + input);
		}
	}

	@Test
	void invalidCodePointsRetainCharacterToCharsExceptionMessages() {
		List<CodePointCase> cases = List.of(
				new CodePointCase("\\u-001", -1),
				new CodePointCase("\\u-FFF", -0xFFF),
				new CodePointCase("\\U-0000001", -1),
				new CodePointCase("\\U00110000", 0x110000),
				new CodePointCase("\\U7FFFFFFF", Integer.MAX_VALUE),
				new CodePointCase("\\U-8000000", -0x8000000));
		for (CodePointCase testCase : cases) {
			IllegalArgumentException expected = assertThrows(IllegalArgumentException.class,
					() -> Character.toChars(testCase.codePoint()));
			String input = "prefix\\t" + testCase.escaped() + "suffix";
			IllegalArgumentException actual = assertThrows(IllegalArgumentException.class,
					() -> NTriplesUtil.unescapeString(input), testCase.escaped());
			assertEquals(expected.getClass(), actual.getClass(), testCase.escaped());
			assertEquals(expected.getMessage(), actual.getMessage(), testCase.escaped());
		}
	}

	private static void assertMessage(String input, String expected) {
		IllegalArgumentException exception = assertThrows(IllegalArgumentException.class,
				() -> NTriplesUtil.unescapeString(input), input);
		assertEquals(IllegalArgumentException.class, exception.getClass(), input);
		assertEquals(expected, exception.getMessage(), input);
	}

	private record CodePointCase(String escaped, int codePoint) {
	}
}
